class Solution:
    def detectCapitalUse(self, word: str) -> bool:
        return word.isupper() or word.islower() or word.istitle()

class Solution {
public:
    bool detectCapitalUse(string word) {
        int caps = 0;
        for (char c : word) {
            if (isupper(c)) caps++;
        }
        int n = word.size();
        return caps == n || caps == 0 || (caps == 1 && isupper(word[0]));
    }
};

class Solution {
    public boolean detectCapitalUse(String word) {
        int caps = 0;
        for (char c : word.toCharArray()) {
            if (Character.isUpperCase(c)) caps++;
        }
        int n = word.length();
        return caps == n || caps == 0 || (caps == 1 && Character.isUpperCase(word.charAt(0)));
    }
}

var detectCapitalUse = function(word) {
    let caps = 0;
    for (let i = 0; i < word.length; i++) {
        if (word[i] >= 'A' && word[i] <= 'Z') caps++;
    }
    const n = word.length;
    return caps === n || caps === 0 || (caps === 1 && word[0] >= 'A' && word[0] <= 'Z');
};
